<?php
namespace ExcelHerbal\ERP7\Inventory;
use ExcelHerbal\ERP7\Database\Db;
use ExcelHerbal\ERP7\Database\Transaction;
use ExcelHerbal\ERP7\Domain\DomainException;
use ExcelHerbal\ERP7\Security\Actor;
final class StockService{
 public static function product(Actor $a,int $product):array{$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('products')." WHERE id=%d AND company_id=%d AND status='active'",$product,$a->companyId),ARRAY_A);if(!$r)throw new DomainException('Product not found.','product_not_found',404);return$r;}
 public static function commercial(Actor $a,int $product,?string $at=null):array{$db=Db::wpdb();$at=$at?:Db::now();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('product_commercial_revisions')." WHERE company_id=%d AND product_id=%d AND status='active' AND effective_from<=%s ORDER BY effective_from DESC,id DESC LIMIT 1",$a->companyId,$product,$at),ARRAY_A);if(!$r)throw new DomainException('Commercial revision missing.','commercial_missing',409);return$r;}
 public static function validateBatch(Actor $a,array $product,?int $batch,bool $out=false):?array{$mode=(string)$product['batch_tracking'];if($mode==='required'&&!$batch)throw new DomainException('Batch required for product.','batch_required',422);if(!$batch)return null;$db=Db::wpdb();$r=$db->get_row($db->prepare("SELECT * FROM ".Db::table('batches')." WHERE id=%d AND company_id=%d AND product_id=%d AND status='active'",$batch,$a->companyId,(int)$product['id']),ARRAY_A);if(!$r)throw new DomainException('Invalid batch.','batch_invalid',422);if($out&&!empty($r['expires_on'])&&$r['expires_on']<Db::today())throw new DomainException('Expired batch cannot move out.','batch_expired',409);return$r;}
 public static function ensureBatch(Actor $a,array $product,array $line):?int{$id=isset($line['batch_id'])?(int)$line['batch_id']:0;if($id){self::validateBatch($a,$product,$id,false);return$id;}$no=trim((string)($line['batch_no']??''));if((string)$product['batch_tracking']==='required'&&$no==='')throw new DomainException('Batch number required.','batch_required',422);if($no==='')return null;$db=Db::wpdb();$t=Db::table('batches');$sql=$db->prepare("INSERT INTO {$t}(company_id,product_id,batch_no,manufactured_on,expires_on,status,created_at) VALUES(%d,%d,%s,%s,%s,'active',%s) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)",$a->companyId,(int)$product['id'],$no,$line['manufactured_on']??null,$line['expires_on']??null,Db::now());$result=$db->query($sql);if($result===false)throw new DomainException('Batch creation failed.','batch_store_failed',500);$batchId=(int)$db->insert_id;if(!$batchId)$batchId=(int)$db->get_var($db->prepare("SELECT id FROM {$t} WHERE company_id=%d AND product_id=%d AND batch_no=%s",$a->companyId,(int)$product['id'],$no));if(!$batchId)throw new DomainException('Batch creation failed.','batch_store_failed',500);return$batchId;}
 public static function cost(Actor $a,int $branch,int $product,?int $batch=null,?int $custodian=null):float{$db=Db::wpdb();return(float)$db->get_var($db->prepare("SELECT average_unit_cost FROM ".Db::table('stock_balances')." WHERE company_id=%d AND branch_id=%d AND product_id=%d AND batch_key=%d AND custodian_key=%d",$a->companyId,$branch,$product,$batch?:0,$custodian?:0));}
 public static function move(Actor $a,int $branch,int $product,?int $batch,?int $custodian,string $dir,float $qty,float $cost,string $source,int $sourceId):void{if($qty<=0||!in_array($dir,['IN','OUT'],true))throw new DomainException('Invalid stock movement.');$p=self::product($a,$product);self::validateBatch($a,$p,$batch,$dir==='OUT');Transaction::run(function()use($a,$branch,$product,$batch,$custodian,$dir,$qty,$cost,$source,$sourceId){$db=Db::wpdb();$b=Db::table('stock_balances');$bk=$batch?:0;$ck=$custodian?:0;$seed=$db->query($db->prepare("INSERT INTO {$b}(company_id,branch_id,product_id,batch_key,custodian_key,quantity,average_unit_cost,updated_at) VALUES(%d,%d,%d,%d,%d,0,0,%s) ON DUPLICATE KEY UPDATE id=id",$a->companyId,$branch,$product,$bk,$ck,Db::now()));if($seed===false)throw new DomainException('Stock balance initialization failed.','stock_balance_store_failed',500);$r=$db->get_row($db->prepare("SELECT * FROM {$b} WHERE company_id=%d AND branch_id=%d AND product_id=%d AND batch_key=%d AND custodian_key=%d FOR UPDATE",$a->companyId,$branch,$product,$bk,$ck),ARRAY_A);if(!$r)throw new DomainException('Stock balance unavailable.','stock_balance_store_failed',500);$cur=(float)$r['quantity'];$avg=(float)$r['average_unit_cost'];if($dir==='OUT'){if($cur+0.0001<$qty)throw new DomainException('Insufficient stock.','insufficient_stock',409);$next=$cur-$qty;$eff=$avg>0?$avg:$cost;$newAvg=$next>0?$avg:0;}else{$eff=max(0,$cost);$next=$cur+$qty;$newAvg=$next>0?(($cur*$avg)+($qty*$eff))/$next:0;}$updated=$db->update($b,['quantity'=>round($next,3),'average_unit_cost'=>round($newAvg,4),'updated_at'=>Db::now()],['id'=>(int)$r['id']]);if($updated===false)throw new DomainException('Stock balance update failed.','stock_balance_store_failed',500);Db::mustInsert($db,Db::table('stock_ledger'),['company_id'=>$a->companyId,'branch_id'=>$branch,'product_id'=>$product,'batch_id'=>$batch,'custodian_employee_id'=>$custodian,'direction'=>$dir,'quantity'=>$qty,'unit_cost'=>round($eff,4),'source_type'=>$source,'source_id'=>$sourceId,'occurred_at'=>Db::now(),'created_by'=>$a->employeeId]);});}
 public static function transferCustody(Actor $a,int $branch,int $emp,int $product,?int $batch,float $qty,string $source,int $sourceId):float{$cost=self::cost($a,$branch,$product,$batch,null);Transaction::run(function()use($a,$branch,$emp,$product,$batch,$qty,$source,$sourceId,$cost){self::move($a,$branch,$product,$batch,null,'OUT',$qty,$cost,$source,$sourceId);self::move($a,$branch,$product,$batch,$emp,'IN',$qty,$cost,$source,$sourceId);});return$cost;}
}
